__NUXT_JSONP__("/finanzas-publicas/noticias/gasto_en_inversion_fisica_cayo_18-4_anual_pese_a_plan_de_infraestructura", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s){return {data:[{post:{slug:"gasto_en_inversion_fisica_cayo_18-4_anual_pese_a_plan_de_infraestructura",title:"Gasto en inversión física cayó 18.4% anual pese a Plan de Infraestructura",date:"2026-06-04T17:13:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F5d8e20fe-13a3-47d9-bbb3-0b2aabfb9ccd\u002F","img-alt":"Inversión física",autor:"Belén Saldívar, El Economista",link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Feconomia\u002Fgasto-inversion-fisica-cayo-18-4-anual-pese-plan-infraestructura-20260603-816794.html",category:"finanzas-publicas",extracto:"Por cada $100 que se gastó el gobierno, $6.9 se destinaron a ese rubro, mientras que en otros como pensiones y el costo financiero de la deuda, se destinaron $17.6 y $12.3, respectivamente.",toc:[{id:m,depth:e,text:n},{id:o,depth:e,text:p},{id:q,depth:e,text:r}],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"La llave del gasto público en inversión física continuó cerrada en el primer cuatrimestre del año pese al ambicioso Plan de Infraestructura anunciado en febrero pasado por el gobierno de Claudia Sheinbaum, de acuerdo con los datos al mes de abril de la Secretaría de Hacienda y Crédito Público (SHCP)."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Entre enero y abril pasados, el gobierno desembolsó 240,966 millones de pesos a la inversión en infraestructura, la cual se considera un rubro esencial del gasto público para impulsar el crecimiento económico y bienestar social."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Los recursos desembolsados resultaron 18.4% menor a lo que se gastó hace un año, cuando se le pasó tijera al gasto en inversión física para tratar de reducir el déficit fiscal."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"De esta manera, por cada 100 pesos que se gastó el gobierno, 6.9 pesos se destinaron a la inversión física, mientras que en otros rubros como pensiones y el costo financiero de la deuda, dos de las grandes presiones del gasto público, se destinaron 17.6 y 12.3 pesos respectivamente."}]},{type:a,value:c},{type:b,tag:f,props:{id:m},children:[{type:b,tag:g,props:{ariaHidden:h,href:"#hasta-pemex-recibi%C3%B3-menos",tabIndex:i},children:[{type:b,tag:j,props:{className:[k,l]},children:[]}]},{type:a,value:n}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Lo que está pasando este año es un recorte a la inversión, particularmente a Petróleos Mexicanos (Pemex) de 47.4% mientras que la demás inversión, como en salud, educación, gasto funcional en gobierno, tienen una ligera recuperación de 4.7%, pero no está en los mejores niveles observados entre el 2014 y el 2015. Y esto está en un proceso de consolidación fiscal, donde el sacrificado ha sido Pemex”, señaló Jorge Cano, coordinador del Programa de Gasto Público y Rendición de Cuentas de México Evalúa."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A esto se le agrega la incertidumbre comercial y el bajo crecimiento de la economía mexicana este año, agregó Dalia Toledo, directora de Finanzas Públicas y Anticorrupción de la organización Ethos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Lo anterior, añadió, sobre todo en la parte de menor crecimiento ha afectado los ingresos públicos que, en el primer cuatrimestre del año mostraron una contracción de 2.2% anual."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Hay una caída en los ingresos que le impide al gobierno el flujo de recursos para invertir conforme a lo planeado”, agregó."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Este es el segundo año donde el gobierno busca la consolidación fiscal, esto tras el déficit fiscal histórico de 5.7% del Producto Interno Bruto (PIB) del 2024, que ocasionó recortes al gasto el año pasado para tratar de reducir el déficit a 3.9%, meta que se incumplió por los apoyos a Pemex, por lo que los Requerimientos Financieros del Sector Público (RFSP) cerraron el 2025 en 4.8% del PIB."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En tanto, este año el gobierno pretende llevar el déficit a 4.1% del PIB pero, ante la debilidad económica y la caída de los ingresos públicos, para algunos analistas esto queda en duda."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"De mantenerse la inversión con este tipo de caída, al cierre del año el gasto en infraestructura sería de 1.8% del PIB de acuerdo con México Evalúa, menor a 2.2% en el 2025."}]},{type:a,value:c},{type:b,tag:f,props:{id:o},children:[{type:b,tag:g,props:{ariaHidden:h,href:"#desarrollo-econ%C3%B3mico-cay%C3%B3",tabIndex:i},children:[{type:b,tag:j,props:{className:[k,l]},children:[]}]},{type:a,value:p}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Por rubros, se puede observar que de las tres grandes categorías que son: gobierno, desarrollo social y desarrollo económico, fue en esta última donde se observó una mayor caída de la inversión física, con un desplome de 40.7 por ciento."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Dicha caída fue liderada por la función de Turismo, con un gasto 80.4% menor que hace un año; Combustibles, con 43.8% menos recursos; y transporte con 33.9% menos gasto ejercido."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En tanto, la inversión física para el desarrollo social creció 18.5% anual, impulsada principalmente por un aumento de 306% en los recursos que se destinan a la infraestructura para el medio ambiente, así como un incremento de 209% para la salud."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En el caso de la inversión física en gobierno, el gasto creció 16.5% anual en el primer cuatrimestre del año."}]},{type:a,value:c},{type:b,tag:f,props:{id:q},children:[{type:b,tag:g,props:{ariaHidden:h,href:"#la-promesa-de-mayor-inversi%C3%B3n",tabIndex:i},children:[{type:b,tag:j,props:{className:[k,l]},children:[]}]},{type:a,value:r}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En febrero pasado, el gobierno anunció el Plan de Infraestructura que busca impulsar inversiones mixtas, es decir, tanto del sector público como privado, para llegar a un monto total de 5.6 billones de pesos desde este año hasta el 2030."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Si bien el plan plantea tantos recursos públicos como privados, Jorge Cano señaló que difícilmente se verá un repunte importante en el gasto público en inversión física que mes con mes informa la SHCP, ya que se prevé que entre las inversiones mixtas la mayor parte sea privada."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En tanto, Hacienda continúa con la narrativa de que este Plan de Infraestructura impulsará no solo el crecimiento de la inversión, sino también de la economía, que en los tres primeros meses del año sufrió una contracción de 0.6% trimestral."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fgasto_en_inversion_fisica_cayo_18-4_anual_pese_a_plan_de_infraestructura",extension:".md",createdAt:s,updatedAt:s}}],fetch:{},mutations:[]}}("text","element","\n","p",3,"h3","a","true",-1,"span","icon","icon-link","hasta-pemex-recibió-menos","Hasta Pemex recibió menos","desarrollo-económico-cayó","Desarrollo económico cayó","la-promesa-de-mayor-inversión","La promesa de mayor inversión","2026-07-19T00:56:17.244Z")));